resource "aws_instance" "web" {
  ami           = "ami-0abc123"
  instance_type = "t3.micro"

  # Bloc de connexion : dit à Terraform COMMENT joindre la machine
  # (nécessaire pour file et remote-exec).
  connection {
    type        = "ssh"
    user        = "ubuntu"
    host        = self.public_ip     # self = la ressource courante
    private_key = file("~/.ssh/id_rsa")
  }

  # file : copie un fichier local VERS la machine
  provisioner "file" {
    source      = "config/app.conf"
    destination = "/etc/app/app.conf"
  }

  # remote-exec : lance des commandes SUR la machine créée (via SSH)
  provisioner "remote-exec" {
    inline = [
      "sudo apt-get update",
      "sudo apt-get install -y nginx",
    ]
  }

  # local-exec : lance une commande sur TA machine (celle qui exécute Terraform)
  provisioner "local-exec" {
    command = "echo 'Serveur prêt : ${self.public_ip}' >> serveurs.txt"
  }
}

# terraform_data : support natif (remplace null_resource)
resource "terraform_data" "deploy" {
  triggers_replace = [var.app_version]   # rejoue quand la version change

  provisioner "local-exec" {
    command = "echo 'déploiement de ${var.app_version}'"
  }
}

# terraform_data peut aussi juste STOCKER une valeur (input) sans provisioner :
resource "terraform_data" "value" { input = var.config }
